"use client";
import { Button, Form} from "react-bootstrap";
import { useEffect } from "react";
import  {facebook,google,movie1} from  '@/assets';
import Image from "next/image";
import    *  as Yup from 'yup';
import  {useFormik} from  'formik';
import { useAuthStore } from "@/hooks/authHook";
import { toast } from "react-toastify";
import { useRouter } from "next/navigation";
export default function RegisterPage() {
  const error = useAuthStore((state) => state.error);
  const isRegistered = useAuthStore((state) => state.isRegistered);
  const registerUser = useAuthStore((state) => state.registerUser);
  const clearError = useAuthStore((state) => state.clearError);
  const  router = useRouter();


   useEffect(() => {
    if (isRegistered) {
      toast.success("Registration Successful!");
      setTimeout(() => router.push("/login"), 1500);
    } else if (error) {
      toast.error(error);
      clearError();
    }
  }, [isRegistered, error, router]); 
  
 const formik = useFormik({
      initialValues: {
        firstName: "",
        lastName: "",
        email: "",
        password: "",
        confirmPassword: "",
        acceptanceMessage: false,
        enableReinitialize: true,
      },
      validationSchema: Yup.object({
        firstName: Yup.string().max(10, "Must be 10 characters or less").required("Required"),
        lastName: Yup.string().max(5, "Must be 5 characters").required("Required"),
       
        email: Yup.string().email("Invalid email").required("Required"),
        password: Yup.string().min(8, "Min 8 characters").required("Required"),
        confirmPassword: Yup.string().oneOf([Yup.ref("password")], "Passwords must match").required("Required"),
        acceptanceMessage: Yup.boolean()
          .oneOf([true], "Please confirm first")
          .required("Required"),
      }),
     onSubmit: (values) => {
        registerUser({
          email: values.email,
          firstName: values.firstName,
          lastName: values.lastName,
          confirmPassword:values.confirmPassword,
          password: values.password,
          acceptanceMessage:values.acceptanceMessage
        });
      },
    }); 
  return (
     <div className=" position-relative vh-100 vw-100 d-flex justify-content-center align-items-center">
    <Image
      src={movie1.src}
      alt="background"
      priority
      fill
      unoptimized
      style={{
        objectFit:"cover",         
        opacity:0.7,
      }}
    />
    <Form 
      onSubmit={formik.handleSubmit} 
       className="p-5 border-3 rounded-4 shadow-lg text-primary fw-bold"
  style={{ 
    width: "100%",      
    maxWidth: "500px",    
    height: "auto",    
    backgroundColor: "rgba(255, 255, 255, 0.85)",
    backdropFilter: "blur(10px)" 
  }}>
        <h3 className="text-center">
          Register</h3>
        <Form.Group className="mb-3">
          <Form.Label>First Name</Form.Label>
          <Form.Control
            name="firstName"
            type="text"
            onChange={formik.handleChange}
            value={formik.values.firstName}
            onBlur={formik.handleBlur}
            autoComplete="none"
            placeholder="Enter  the First Name"
            isInvalid={!!(formik.touched.firstName && formik.errors.firstName)}
          />
          <Form.Control.Feedback type="invalid">
            {formik.errors.firstName}
          </Form.Control.Feedback>
        </Form.Group>
        <Form.Group className="mb-3">
          <Form.Label>Last Name</Form.Label>
          <Form.Control
            name="lastName"
            type="text"
            onChange={formik.handleChange}
            value={formik.values.lastName}
            onBlur={formik.handleBlur}
            autoComplete="none"
            placeholder="Enter the last Name"
            isInvalid={!!(formik.touched.lastName && formik.errors.lastName)}/>
          <Form.Control.Feedback type="invalid">
            {formik.errors.lastName}
          </Form.Control.Feedback>
        </Form.Group>
        <Form.Group className="mb-3">
          <Form.Label>Email Address</Form.Label>
          <Form.Control
            name="email"
            type="email"
            onChange={formik.handleChange}
            value={formik.values.email}
            onBlur={formik.handleBlur}
            autoComplete="none"
            placeholder="Enter the  email  Address"
            isInvalid={!!(formik.touched.email && formik.errors.email)}
          />
          <Form.Control.Feedback type="invalid">
            {formik.errors.email}
          </Form.Control.Feedback>
        </Form.Group>
        <Form.Group className="mb-3">
          <Form.Label>Password</Form.Label>
          <Form.Control
            name="password"
            type="password"
            onChange={formik.handleChange}
            placeholder="Enter the password"
            onBlur={formik.handleBlur}
            value={formik.values.password}
            autoComplete="none"
            isInvalid={!!(formik.touched.password && formik.errors.password)}/>
          <Form.Control.Feedback type="invalid">
            {formik.errors.password}
          </Form.Control.Feedback>
        </Form.Group>
        <Form.Group className="mb-3">
          <Form.Label>Confirm Password</Form.Label>
          <Form.Control
            name="confirmPassword"
            type="password"
            autoComplete="none"
            placeholder="Enter the confirm-password"
            onChange={formik.handleChange}
            onBlur={formik.handleBlur}
            value={formik.values.confirmPassword}
            isInvalid={!!(formik.touched.confirmPassword && formik.errors.confirmPassword)}/>
          <Form.Control.Feedback type="invalid">
            {formik.errors.confirmPassword}
          </Form.Control.Feedback>
        </Form.Group>
           <Form.Group className="mb-3">
          <Form.Check
            name="acceptanceMessage"
            type="checkbox"
            autoComplete="none"
            checked={formik.values.acceptanceMessage}
            onChange={formik.handleChange}
            label= "I agree to the Terms and Conditions and Privacy Policy."
            isInvalid={!!(formik.touched.acceptanceMessage && formik.errors.acceptanceMessage)}
          />
          <Form.Control.Feedback type="invalid">
            {formik.errors.acceptanceMessage}
          </Form.Control.Feedback>
        </Form.Group>
        <div className="d-flex justify-content-center">
          <Button size="lg" type="submit">
            Register
          </Button>
        </div>
        <div className="d-flex align-items-center my-4">
          <hr className="flex-grow-1" />
          <span className="mx-2 text-muted">or continue with</span>
          <hr className="flex-grow-1"/>
        </div>
        <div className="d-grid gap-2">
          <Button
            variant="outline-dark"
            className="d-flex align-items-center justify-content-center py-2"
            onClick={() => router.push("https://www.google.com/")}
          >
            <img src={google.src} alt="Google" width="20" className="me-2" />
            Continue with Google
          </Button>
          <Button
            variant="primary"
            style={{ backgroundColor: "white", borderColor: "#1877F2", color:"black" }}
            className="d-flex align-items-center justify-content-center py-2"
            onClick={() => router.push("https://www.facebook.com/")}
          >
            <img
              src={facebook.src}
              alt="Facebook"
              width="20"
              className="me-2"
            />
            Continue with Facebook
          </Button>
        </div>
      </Form>
    </div>
  );
}
